// Read-only inspection of given components and media
const out = {};

function inspect(id, label) {
  const n = figma.getNodeById(id);
  if (!n) { out[label] = 'NOT FOUND'; return; }
  const info = { type: n.type, w: n.width, h: n.height };
  if ('fills' in n) info.fills = JSON.parse(JSON.stringify(n.fills));
  if ('strokes' in n) info.strokes = JSON.parse(JSON.stringify(n.strokes));
  if ('cornerRadius' in n) info.radius = n.cornerRadius;
  if ('effects' in n) info.effects = JSON.parse(JSON.stringify(n.effects));
  if ('children' in n) {
    info.children = n.children.map(c => {
      const ci = { name: c.name, type: c.type };
      if ('fills' in c) ci.fills = JSON.parse(JSON.stringify(c.fills));
      if ('strokes' in c) ci.strokes = JSON.parse(JSON.stringify(c.strokes));
      if ('cornerRadius' in c) ci.radius = c.cornerRadius;
      if (c.type === 'TEXT') {
        ci.chars = c.characters;
        ci.font = c.fontName && c.fontName.style ? c.fontName.style + ' ' + c.fontSize : null;
        ci.fills = JSON.parse(JSON.stringify(c.fills));
      }
      return ci;
    });
  }
  out[label] = info;
}

